import { NO_COPY_CLASS } from "@hunt/copy-to-clipboard";
import { Button } from "@hunt/shadcn";
import { cn } from "@hunt/styled-ui";
import React, { useCallback, useState, useEffect } from "react";

export const GLITCH_PUZZMON_BEFRIENDED_KEY = "glitch-puzzmon-befriended";

export function GlitchBefriendButton() {
  const [befriended, setBefriended] = useState(false);

  useEffect(() => {
    if (typeof window === "undefined") {
      return;
    }
    setBefriended(
      localStorage.getItem(GLITCH_PUZZMON_BEFRIENDED_KEY) === "true",
    );
  }, []);

  const handleBefriend = useCallback(() => {
    if (!befriended) {
      localStorage.setItem(GLITCH_PUZZMON_BEFRIENDED_KEY, "true");
      setBefriended(true);
      window.dispatchEvent(new CustomEvent("glitch-puzzmon-befriended"));
    }

    if (typeof window === "undefined") {
      return;
    }
    const currentUrl = new URL(window.location.href);
    currentUrl.searchParams.set("showMonarch", "true");
    currentUrl.searchParams.set("puzzmonSlug", "glitchy");
    window.history.pushState({}, "", currentUrl.toString());
    window.dispatchEvent(new CustomEvent("monarch-open"));
  }, [befriended]);

  return (
    <div className={cn("flex justify-center", NO_COPY_CLASS)}>
      <Button onClick={handleBefriend}>
        {befriended
          ? "View Glitchy's Monarch entry"
          : "Befriend the Glitch Puzzmon"}
      </Button>
    </div>
  );
}
